# Exports the data used by PTC-python from the R package PTC (version 1.1.2)
# and miRBaseConverter. Run from the repository root:
#   Rscript scripts/PTC.ExportData.R
# The files in src/ptc/data and tests/expected are generated by this script.
suppressMessages({library(PTC); library(miRBaseConverter)})
out <- "src/ptc/data"
gz <- function(x, file) {
  con <- gzfile(file.path(out, file), "w")
  write.csv(x, con, row.names = FALSE)
  close(con)
}

# TargetScan 7.0 predicted interactions (miRBase v21 names)
data(TScan)
gz(data.frame(miRNA = TScan[, 1], mRNA = TScan[, 2]), "TScan.csv.gz")

# TargetScan 7.0 context++ scores (only the columns PTC uses)
data(TS7.0_Conserved_Site_Context_Scores)
ctx <- TS7.0_Conserved_Site_Context_Scores
gz(data.frame(Gene.Symbol = ctx$Gene.Symbol, miRNA = ctx$miRNA,
              context.score = ctx[["context...score"]]), "TS7.0_context_scores.csv.gz")

# Experimentally confirmed interactions (miRTarBase, TarBase, miRWalk)
data(GroundT)
gz(data.frame(mRNA = rep(names(GroundT), lengths(GroundT)),
              miRNA = unlist(GroundT, use.names = FALSE)), "GroundT.csv.gz")

# miRBase v21 conversion table: for every miRNA name known to miRBaseConverter,
# the v21 names it maps to, in the order miRNAVersionConvert() returns them
syms <- unique(gsub("\\..*", "", getFromNamespace("SYM", "miRBaseConverter")))
conv <- miRNAVersionConvert(syms, targetVersion = "v21", exact = FALSE, verbose = FALSE)
conv <- conv[!is.na(conv$TargetName), c("OriginalName", "TargetName")]
gz(conv, "miRBase_v21.csv.gz")

# Expression matrices are saved exactly: the values as raw 64-bit numbers
# (column by column, xz-compressed) and the sample and gene names as text
writeMatrix <- function(x, name) {
  con <- xzfile(file.path(out, paste0(name, ".f64.xz")), "wb")
  writeBin(as.vector(x), con, size = 8, endian = "little")
  close(con)
  con <- gzfile(file.path(out, paste0(name, ".names.txt.gz")), "w")
  writeLines(c(paste(rownames(x), collapse = "\t"), paste(colnames(x), collapse = "\t")), con)
  close(con)
  # check that the file reads back identically
  con <- xzfile(file.path(out, paste0(name, ".f64.xz")), "rb")
  back <- readBin(con, "double", n = length(x), size = 8, endian = "little")
  close(con)
  stopifnot(identical(back, as.vector(unname(x)) + 0))
}

# Example data: single-cell (prepared as in inst/PTC.MainApplication.R) and TCGA BRCA
SC <- PTC:::prepareSCdata()
writeMatrix(SC$miRs, "SC_miRNAs")
writeMatrix(SC$mRNAs, "SC_mRNAs")
data(TCGA_BRCAdata)
writeMatrix(TCGA_BRCAdata$miRs, "TCGA_BRCA_miRNAs")
writeMatrix(TCGA_BRCAdata$mRNAs, "TCGA_BRCA_mRNAs")

# Wanderlust pseudotime of the single-cell data, copied from data/wandTime.csv
# of the R package repository (set PTC_R_REPO to its folder)
ptc_repo <- Sys.getenv("PTC_R_REPO", "../PTC")
file.copy(file.path(ptc_repo, "data", "wandTime.csv"), file.path(out, "wandTime.csv"), overwrite = TRUE)
wandTime <- read.csv(file.path(out, "wandTime.csv"), header = FALSE)

# check that the context scores read back identically from the CSV
back <- read.csv(file.path(out, "TS7.0_context_scores.csv.gz"))
stopifnot(identical(back$context.score, ctx[["context...score"]]))
cat("export done\n")

# Expected results for the tests: PTC() with the settings of the paper
# (inst/PTC.MainApplication.R), as text files
expected <- "tests/expected"
writeResult <- function(res, name) {
  write.csv(res$Summary, file.path(expected, paste0(name, "_summary.csv")), row.names = FALSE)
  parents <- data.frame(mRNA = rep(names(res$Names), lengths(res$Names)),
                        miRNA = unlist(res$Names, use.names = FALSE))
  write.csv(parents, file.path(expected, paste0(name, "_parents.csv")), row.names = FALSE)
}
res <- suppressWarnings(suppressMessages(PTC(SC$miRs, SC$mRNAs, VIM = SC$mRNAs[, "VIM"])))
writeResult(res, "sc")
res <- suppressWarnings(suppressMessages(PTC(SC$miRs, SC$mRNAs, VIM = unlist(wandTime))))
writeResult(res, "sc_wanderlust")
writeLines(sprintf("%a", unlist(wandTime)), file.path(expected, "wandTime.txt"))
res <- suppressWarnings(suppressMessages(PTC(TCGA_BRCAdata$miRs, TCGA_BRCAdata$mRNAs,
                                              VIM = TCGA_BRCAdata$mRNAs[, "VIM"])))
writeResult(res, "tcga")
cat("expected results done\n")

# Other parameter settings (smaller selections, TCGA BRCA)
X <- TCGA_BRCAdata
variants <- list(
  first_set   = list(nmiR = 15, nmR = 150, explore.all = FALSE),
  pairwise    = list(nmiR = 15, nmR = 150, complements = FALSE, ngrid = 3, alpha = 0.05),
  own_tscan   = list(nmiR = 15, nmR = 300, TScan = TScan[seq(1, nrow(TScan), by = 2), ]),
  ngrid4      = list(nmiR = 20, nmR = 200, ngrid = 4, alpha = 0.01))
for (v in names(variants)) {
  res <- suppressWarnings(suppressMessages(do.call(PTC, c(list(X$miRs, X$mRNAs, VIM = X$mRNAs[, "VIM"]), variants[[v]]))))
  writeResult(res, paste0("tcga_", v))
}

# p-values of the decoupled test for many sets of predictors (TCGA BRCA)
dt <- getFromNamespace("decoupledTest", "PTC")
Sel <- suppressMessages(PTC.GeneSel(PTC.ptime(X, X$mRNAs[, "VIM"]), 30, 1500))
genes <- Sel$mRs[lengths(Sel$PParents[Sel$mRs]) > 0]
rows <- list(); n <- 0
for (g in genes) {
  Xg <- Sel$d[, Sel$PParents[[g]], drop = FALSE]; Yg <- Sel$d[, g, drop = FALSE]
  for (k in seq_len(min(ncol(Xg), 3))) {
    S <- combn(ncol(Xg), k)[, 1]
    for (comp in c(TRUE, FALSE)) {
      ng <- if (comp) 2 else 3
      grid <- as.integer(seq(0, nrow(Xg), length.out = ng + 1))
      set.seed(n)
      p <- dt(Xg, Yg, S, grid = grid, complements = comp, B = 100)
      rows[[length(rows) + 1]] <- data.frame(gene = g, seed = n, S = paste(S, collapse = " "),
                                             complements = comp, ngrid = ng, p = p)
      n <- n + 1
    }
  }
}
write.csv(do.call(rbind, rows), file.path(expected, "tcga_pvalues.csv"), row.names = FALSE)

# R random numbers (exact, in hexadecimal) and miRBase v21 conversions
set.seed(1); a <- rnorm(5000); set.seed(12345); b <- rnorm(1000)
writeLines(sprintf("%a", c(a, b)), file.path(expected, "rnorm.txt"))
odd <- c("hsa-mir-21", "hsa-miR-21", "hsa-let-7a-1.2", "hsa miR 21", "notamirna", "hsa-miR-92a")
for (b in list(list("tcga", colnames(X$miRs)), list("sc", colnames(SC$miRs)), list("odd", odd))) {
  write.csv(data.frame(name = b[[2]], v21 = suppressMessages(PTC.miRv21(b[[2]]))),
            file.path(expected, paste0("mirv21_", b[[1]], ".csv")), row.names = FALSE)
}
cat("variants done\n")
